DECLARE
    l_blob BLOB;
    l_raw  RAW(32767);
BEGIN
    UPDATE sp_team_members
       SET photo = EMPTY_BLOB()
     WHERE screen_name = 'aclarke'
    RETURNING photo INTO l_blob;

    l_raw := HEXTORAW('');
    DBMS_LOB.WRITEAPPEND(l_blob, UTL_RAW.LENGTH(l_raw), l_raw);

END;
/

