    l_raw := HEXTORAW('7FCBF87FD7FF5D2FC7EBFF034891A3675736BF900000000049454E44AE426082');
    DBMS_LOB.WRITEAPPEND(l_blob, UTL_RAW.LENGTH(l_raw), l_raw);

update sp_team_members
   set photo_mimetype = 'image/png',
       photo_lastupd  = sysdate,
       photo_filename = screen_name||'.png'
 where photo_mimetype is null
   and photo is not null;

END;
/